SELECT id, action, entity, entity_id,
CAST(before_data AS CHAR) AS before_data,
CAST(after_data AS CHAR)  AS after_data,
user_id, ip_address, created_at
FROM audit_log WHERE 1=1

    AND action = #{action}


    AND entity = #{entity}

ORDER BY created_at DESC
LIMIT #{size}
